namespace gui_forms {

// ScaledPanel's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/scaled_panel.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// How the design space maps onto the arranged size (stage VA, decision 10): stretch, each axis at its own ratio (the default), or uniform, one scale (the smaller axis ratio) keeping the design's proportions, aligned by viewport_fit's alignment. Either is an explicit, recorded stretch. Throws std::invalid_argument for a value outside ScaledAspect.
template <typename Declaring>
struct ScaledPanelAspectCapability {
    PropertyCell<ScaledAspect, ScaledPanelAspectCapability<Declaring>> aspect{ScaledAspect::stretch};

    static void assign(ScaledPanelAspectCapability& capability, ScaledAspect incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.aspect), incoming);
        if (!capability.aspect.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.aspect));
    }
};

// Every ScaledPanel capability, in the order the declaring class takes them.
template <typename Declaring>
struct ScaledPanelCapabilities : public ScaledPanelAspectCapability<Declaring> {};

} // namespace gui_forms
